import { BlockActions, ButtonStyle, getBlockBuilder, IModify, block } from "@rocket.chat/apps-engine/definition/uikit";
import { blocknewButtonElement, blocknewPlainTextObject } from "@rocket.chat/apps-engine/definition/uikit/blocks/components/button";

export class InitiatorMessage implements IModify {
  public async run(modify: IModify): Promise<void> {
    const greetBuilder = getBlockBuilder();

    // Add a section block with a text element
    greetBuilder.addSectionBlock({
      text: block.newPlainTextObject("Hi there! Click the buttons below to select your favorite meme category:"),
    });

    // Add an actions block with buttons for meme categories
    greetBuilder.addActionsBlock({
      blockId: "subreddits",
      elements: [
        block.newButtonElement({
          actionId: "memeSelect",
          text: block.newPlainTextObject("Programmer Humor"),
          value: "programmerhumor",
          style: ButtonStyle.PRIMARY,
        }),
        block.newButtonElement({
          actionId: "memeSelect",
          text: blocknewPlainTextObject("Wholesome Memes"),
          value: "wholesomememes",
          style: ButtonStyle.PRIMARY,
        }),
        // Add more button elements as needed
      ],
    });

    await modify
      .getCreator()
      .finish(greetBuilder);
  }
}
```

Feel free to adjust the code to your needs and the specific context of your RocketChat app. Make sure to include the necessary imports and ensure the code complies with the TypeScript syntax and conventions.
